insert into public.testimonials (id, agent_id, client_name, quote, created_at)
values
  ('06389e6b-dff6-4d04-8720-e9310a653d84', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Wayne Eng', 'It has been a pleasure working with Scott. He was very active, patient, and honest.', '2026-08-14T04:12:04.751675+00:00'),
  ('5959aa69-e64e-44ee-a7eb-479961438d00', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Marisa', 'Scott was amazing, the best there is! We loved working with him and getting to know him as a person.', '2026-08-14T04:12:04.751675+00:00'),
  ('7a7cc4f4-9050-4366-bc01-fb325d5921c6', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Breanna Whittaker', 'Scott Bird was very helpful, always there when I texted or called.', '2026-08-14T04:12:04.751675+00:00'),
  ('bdf48862-b4f0-44c1-aa80-f10d932c4352', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Tom Comstock', 'Scott provided me with a lead on an investment property that turned out to be just what I was looking for.', '2026-08-14T04:12:04.751675+00:00'),
  ('57241692-f679-4b57-bf05-3b666c29f5cd', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Joe', 'Scott''s knowledge of market conditions and realities of the market was a big help.', '2026-08-14T04:12:04.751675+00:00'),
  ('9ae41de9-4d46-498d-af27-dc8aaf8f1d38', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Kevin', 'Scott is the best realtor in the area — he helped me out of several problems.', '2026-08-14T04:12:04.751675+00:00'),
  ('47c7bfc1-b8e5-40d5-b8be-c64ac1c2c4ea', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Kirt', 'Scott did a great job in negotiating with the seller on price.', '2026-08-14T04:12:04.751675+00:00'),
  ('5e60e629-7c6b-42f0-b444-7f9445a70334', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Judy L.', 'Scott Bird was very responsive, understood my needs/interests, put my needs before the company''s.', '2026-08-14T04:12:04.751675+00:00'),
  ('ec82a5f5-46c5-4220-a88c-25fa5ce24efb', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Karen Watterson', 'Scott was one of the only Realtors that we truly trusted and wanted to have our business. He is knowledgeable, and trustworthy. What a wonderful experience to work with him. Thanks Scott', '2026-08-14T04:12:04.751675+00:00'),
  ('8b7a0da9-ef4e-4da4-ac8f-6bef39c29444', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Anthony Ruggiero', 'Scott gave me the information I needed to make the best decision for me and my family.', '2026-08-14T04:12:04.751675+00:00'),
  ('677a4f3f-575c-4cc3-b5b3-5527c574b6d1', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Denny Orton', 'It has truly been a nice experience working with Scott selling property.', '2026-08-14T04:12:04.751675+00:00'),
  ('2f1de091-a277-4bc1-9487-1e1e06c5c52d', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'James Thompson', 'Scott is easy to work with and very knowledgeable in real estate matters.', '2026-08-14T04:12:04.751675+00:00'),
  ('ae443452-81ff-4445-8057-4cf66cd47141', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Joshua Bonzo', 'When my Father passed away, we had a very limited time to clear out his house and prepare it for selling. Scott did far more than just help us sell: While we were in town to prepare the house, Scott helped us find a place to stay, and even arranged to move some things from the house when the moving company backed out on us. He went far above and beyond. In a time of genuine need, Scott helped us on both a professional and personal level. I''d recommend him to anyone!', '2026-08-14T04:25:09.661678+00:00'),
  ('6fbd0556-64bb-4ad3-823b-40c0891ba947', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Kelby Brandow', 'Scott was extremely helpful with a tricky situation… Highly recommend!', '2026-08-14T04:25:09.661678+00:00'),
  ('15d744b6-e979-44a8-ad06-034c56e6db3c', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Jennifer Cheney', 'Scott is a top notch realtor!! He is so generous with his time and knowledge! We highly recommend him and will trust him with any future real estate transactions we might have.', '2026-08-14T04:25:09.661678+00:00'),
  ('e4173780-6154-4bdc-b56d-488f6ccee2fc', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Robert Broadbent', 'Scott did a good job. We love our house.', '2026-08-14T04:25:09.661678+00:00'),
  ('8255e9d5-f787-417d-b07d-a9bd6a5ae7d4', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Lisa Evans', 'Scott helped us buy our house and was so great to work with! Personable and friendly and very helpful. He is one who went out of his way to get the job done and made house hunting a good experience. I would highly recommend having him help you sell or find your next home! Thanks Scott!', '2026-08-14T04:25:09.661678+00:00'),
  ('68d660c9-dd41-4a97-b1fe-543881710944', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Christine Proctor', 'Scott was very helpful with the sale of my home from my first phone call to the closing. He advised me of all options and kept me informed each step of the way. He is caring, personable, and professional. His experience and kindness made me feel confident with my decisions as we navigated this big change in my life. He truly cares about the individual needs and situations of his clients. I recommend him to everyone who is selling or buying a home.', '2026-08-14T04:25:09.661678+00:00'),
  ('69f4d2ff-16be-409b-93da-7c2e3c8579f8', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'David Busk', 'Scott is great to work with and serves his clients well!', '2026-08-14T04:25:09.661678+00:00'),
  ('1588ebb3-5233-4591-b405-28f2fa9eab80', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Kevin Tice', 'Scott Bird sets the standard for real estate agents! He was patient with us while we searched for and selected a home to purchase. Since we were moving from out of state, he helped deal with the logistics associated with the builder, home inspector, and many other issues that we weren''t able to handle from afar. He''s a great communicator and we would definitely recommend him to anyone!', '2026-08-14T04:25:09.661678+00:00'),
  ('e2439e3c-9365-43a4-b959-bfb9d615724e', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Nathaniel Nevins', 'Scott is one the most genuine people I know. He''s fun to work with and really seeks your best interest. I thoroughly enjoyed working with Scott on the sale of our home. If I could give him 8 stars I would!', '2026-08-14T04:25:09.661678+00:00'),
  ('27a7a30c-7fa0-4588-90ba-b8315993330d', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Kristen Nevins', 'Scott Bird is a "more than 5 stars" real estate agent. He''s not just good at his job, he''s a good person. He''s steady, knowledgeable, present, and honest. He will work hard for you and he will really show up for you. He helped us sell our home in a really tough market and I could never recommend a better real estate agent. And he doesn''t use the tacky and borderline dishonest tactics I often see other agents use. I highly recommend Scott Bird!', '2026-08-14T04:25:09.661678+00:00'),
  ('80f00c21-2720-446d-8533-98186b589a1b', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Chris & Brenda Saletta', 'Being new to Cedar City/St George, we were nervous about finding a good realtor without knowing anyone. Luckily, we found Scott Bird and he was a great asset in helping us find our new home and helped us learn a lot of great info about this area. We never felt any pressure to hurry up and make a decision and had a great time looking at houses with Scott. When the time came to make an offer, Scott was able to make the deal happen and he even caught a few errors (by someone else) that saved us thousands. Even after the sale was completed, Scott was always there for any questions that we had. Scott was not only just a realtor to us, he also became a friend and a great person to be around.', '2026-08-14T04:25:09.661678+00:00'),
  ('64a26be4-a670-48f3-88b1-b1f6229ad94e', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Catherine Webb', 'I''ve never experienced a realtor quite like Scott Bird. Scott is professional, kind and truly cares about the clients he works with. He spent so much time with my daughter and me to find the perfect home. He never felt rushed, put out, or frustrated when we wanted to see just one more. He continues to engage and his follow up is outstanding. Scott will be our family''s realtor moving forward for all of our purchasing needs. I highly recommend Scott to anyone who is looking to purchase or sell their home. He is the BEST!', '2026-08-14T04:25:09.661678+00:00'),
  ('29351e44-bf5b-4fdf-bce8-9f9f956208e9', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Jason Murray', 'Scott is a great realtor and if you are buying or selling in Utah, he is the one you want making it happen. He helped shepherd our offer and purchase through with minimal hiccups and the closing was smooth. We love our new house. Thank you Scott! You are the best!', '2026-08-14T04:25:09.661678+00:00'),
  ('c549c010-c16d-4ed0-a402-6707914aef13', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Jesse Carter Team', 'Scott did a great job at getting this deal to the finish line. He is steady and consistent.', '2026-08-14T04:25:09.661678+00:00'),
  ('e7bb6275-64a1-4f27-8eda-993b1f225dd7', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Court Hansen', 'We couldn''t be happier with our experience building a home with Scott Bird! From start to finish, he was professional, detail-oriented, and committed to quality craftsmanship. He made the process smooth and stress-free, always keeping us informed. If you''re looking for an agent who truly cares about their work and their clients, we highly recommend Scott Bird!', '2026-08-14T04:25:09.661678+00:00'),
  ('4d8d72d0-3864-4db7-9af3-63f462f347c7', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Lance', 'Scott and his team really go above and beyond, when it comes to renting or buying a home.', '2026-08-14T04:25:09.661678+00:00'),
  ('3cff48fc-59f0-4b37-8e59-7f17a879cedd', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Cammy Richardson', 'Scott was so wonderful! He helped us buy our first house together. We are so happy with everything he did for us! He drove far out of his way to help us many times! He is wonderful! I highly recommend him!', '2026-08-14T04:25:09.661678+00:00'),
  ('0f60f92c-7c95-42e6-93a8-937dcd10448a', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Savannah Smith', 'Scott is the best in Utah! He is so knowledgeable and genuinely wants the best for those he works with. He has helped us sell our house, and we got asking price within a week. When he helped us start the process of buying a house, he was a great advocate for us and was flexible as things changed. I would recommend Scott to anyone and everyone!', '2026-08-14T04:25:09.661678+00:00'),
  ('68a1d937-9dda-4148-aa4c-b72254ed688c', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Anthony Ruggiero', 'Scott is an incredible realtor. Scott is very professional, experienced, and knowledgeable. Scott is one of the best realtors in Iron County.', '2026-08-14T04:25:09.661678+00:00'),
  ('781b60aa-0fe8-4ea7-960e-663542520e41', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Gina Crawford', 'Working with Scott Bird was such a great experience! He helped me sell my house and made the whole process feel way less stressful than I expected. Scott is super knowledgeable, responsive, and just an all-around amazing person to work with. He took the time to understand my needs, gave honest advice, and guided me every step of the way. He truly cared about helping me and I felt like I could trust him completely. I couldn''t be happier with how everything turned out. I highly recommend Scott to anyone looking for a reliable and dedicated real estate agent!', '2026-08-14T04:25:09.661678+00:00'),
  ('e4ccec09-048e-4731-94e9-f9b7ca623bf5', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Jaxon Haderlie', 'Best in the business! Scott is honest, a great communicator, and extremely knowledgeable. Highly recommend!', '2026-08-14T04:25:09.661678+00:00'),
  ('c24b9dd1-318d-48d7-9054-7e2e8033dc31', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Corey Judd', 'Scott is an experienced and capable professional. I highly recommend him for all your real estate needs.', '2026-08-14T04:25:09.661678+00:00'),
  ('8f3cf002-4033-443b-94d6-8fa00a141089', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Timothy Johnson', 'Had some questions about how to find the value of our home and he gave me multiple different ways to calculate it! Scott Bird and his team are very helpful when it comes to anything real estate!', '2026-08-14T04:25:09.661678+00:00'),
  ('b72d26aa-17ed-4792-89db-3e084d61c90d', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Adam Wilcock', 'Scott took great care of us in selling our house! He made sure we had great pictures taken for showing the house. He also communicated with us every step of the way. He helped us maneuver the requests of the buyers and set up a deal we felt good about. I had myriad questions and he was great at answering them or telling me he didn''t know and finding out for me. He also coordinated with the agent for the house we were buying so that both could close at the same time. Overall, Scott is professional, helpful, and someone I would recommend to anyone!', '2026-08-14T04:25:09.661678+00:00'),
  ('f8ba0bcc-1ae2-4308-a5c0-e2338e40b580', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Jared Van Meter', 'Scott Bird is not only an amazing realtor, but an amazing human being. Scott truly cares about others and builds positivity in everyone around him. Scott Bird works hard because he cares.', '2026-08-14T04:25:09.661678+00:00'),
  ('8bc44a54-b96d-49da-b2c0-1197d8155ea2', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Dallin Rice', 'Working with Scott was an amazing experience! From start to finish, they were professional, responsive, and truly had my best interests in mind. They made the home-buying process smooth and stress-free, always answering my questions and offering valuable advice. I''m so happy with my new home and highly recommend Scott to anyone looking to buy or sell!', '2026-08-14T04:25:09.661678+00:00'),
  ('6f585071-be9b-4cf4-ada6-408390798a9f', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Jeff Mabbutt', 'Scott Bird has helped me out with a couple of real estate transactions. Scott is extremely knowledgeable about the Southern Utah market. When we were looking for a place to purchase, he took the time to get to know us & what our needs were. A few years later when it was time to sell, once again Scott went above and beyond to make the process easy & stress free. If you are looking for real estate in Southern Utah Scott Bird is the go to guy.', '2026-08-14T04:25:09.661678+00:00'),
  ('5a3ae9f7-7888-4354-9908-3206290ca42a', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Nathan Belshaw', 'He is always willing to answer any questions even when it is not one of his properties. He is very quick to respond and is always friendly and professional. Would strongly recommend him to anyone looking to buy real estate in the area!', '2026-08-14T04:25:09.661678+00:00'),
  ('e22d6b74-9d5f-4972-8318-a131a4eb648d', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Aaron Galpin', 'Scott thank you so much for all your help in finding us the perfect vacation home. You made it easy and found us what we wanted.', '2026-08-14T04:25:09.661678+00:00'),
  ('a5b7ac25-1e4f-4dcc-a25e-afd3ce5e06a9', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Mike Wright', 'Scott assisted us with a long distance sale of our late father''s property. We live in Fairbanks Alaska and the house was in St. George Utah. He provided us with great advice so that we were able to get the house cleared out and ready to be listed in only one trip south. We had a full price offer within a week of Scott listing the property. Scott continued to keep us well informed as needed until closing. Scott asked us what we were looking for in a Realtor. We answered someone we could trust which meant they were both competent and of good character. Scott delivered both!', '2026-08-14T04:25:09.661678+00:00'),
  ('bde55d0c-c804-4a47-9e2a-90ea471d46f4', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Dennis Porter', 'Fantastic experience. Was able to list and sell our duplexes quickly with no problems. I will recommend Scott to anyone looking for a great realtor.', '2026-08-14T04:25:09.661678+00:00'),
  ('853cad6a-8bab-42e9-9e19-f9d27ea12dfb', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Stephen Allen', 'I''ve worked with Scott on two home purchases. You won''t find anyone better than him. He is a serious professional and extremely competent. He has excellent interpersonal skills and puts his clients above himself. He was an effective advocate to help us get a good deal on our purchases.', '2026-08-14T04:25:09.661678+00:00'),
  ('562031ad-95be-4b02-b7a4-9b8a018a3943', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Jack Davidson', 'Scott was very helpful in preparing an evaluation of my home. He did a comparison of comparable homes in my neighborhood to get a better idea of how much to list it for. He also made good suggestions regarding better preparing it for listing and showing it for sale.', '2026-08-14T04:25:09.661678+00:00'),
  ('34d31d0e-15a4-41fa-9be3-12ab23995af0', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Landon Covington', 'Scott Bird is one of the most trust worthy people I have met. He is an awesome person to have help you for your real estate needs but is also just a phenomenal human being. Would highly recommend anyone to get to know him and/or use his services in real estate.', '2026-08-14T04:25:09.661678+00:00'),
  ('df729a5a-e892-4e0b-9401-72ee3366755b', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Taevey Davis', 'Scott was great to work with! My husband and I were looking for the perfect house for over a year and Scott always made sure we were taken care of. With both of us being younger, we didn''t know very much about this process and how everything works. Scott was patient with us and taught us so much along the way. Not only was he a great realtor, but he was invested in our lives outside of house hunting. We could always trust him to be honest and upfront with us. Scott is definitely a realtor that we would recommend!!', '2026-08-14T04:25:09.661678+00:00'),
  ('4c49f536-d2ab-44f2-834e-d902d3e738dc', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Dave Harkness', 'Scott was kind enough to show me a house last minute on a Friday evening. He is a great guy, fantastic communicator and has an open and honest approach. It was a pleasure meeting him!', '2026-08-14T04:25:09.661678+00:00'),
  ('0b2457d3-cd5a-4793-8930-13448f8b8afb', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Vicki Tyler', 'Scott is an awesome realtor that we have now used to buy and sell 2x. He pays attention to your needs/price point and also partners with out-of-town agents to ensure there is a local contact! Thanks Scott!', '2026-08-14T04:25:09.661678+00:00'),
  ('47413eb1-6ad6-4568-8d73-9364c931fd4f', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Amanda Hanson', 'Scott is the best in Cedar City! We''ve worked with him on buying and selling both commercial real estate and multiple family homes in Cedar City and every time is a fabulous experience. He is incredibly experienced and knowledgeable and has never steered us wrong with his advice. He listens and genuinely cares about doing what''s best for his clients. He also has excellent integrity and it shows in his work. He has awesome contacts for everything you need, saving you the time of having to hunt down good people yourself to do repairs, painting, curb appeal, etc. He goes above and beyond in every way and is willing to help with things most others wouldn''t in order to make sure his clients are taken care of. We wouldn''t dream of using anyone else for any of our real estate needs!', '2026-08-14T04:25:09.661678+00:00'),
  ('b1659e8c-237f-41f0-8417-d950792dbaf6', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Levi Price', 'Scott was fantastic to work with. He had our best interests at heart and was very helpful in helping us understand our options.', '2026-08-14T04:25:09.661678+00:00'),
  ('4d776650-fb1a-4224-991a-75897da08eda', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Amanda Williams', 'Scott was a pleasure to work with and kind. He helped us find a piece of property to fit our needs and stayed with us every step. When communication with the seller was spotty, he was diligent in contacting their agent for updates and kept us informed. We will definitely use Scott for any future real estate endeavors!', '2026-08-14T04:25:09.661678+00:00'),
  ('243b2b6b-e209-40d0-9cfc-84e29125d872', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Adrianna Connor', 'Scott is the best!! He made it easy to buy a beautiful Cedar City home while living out of state! So thankful for his expertise and knowledge. He is the realtor to use for Southern Utah!', '2026-08-14T04:25:09.661678+00:00'),
  ('38bd19be-ba6c-4b46-8f80-5e7ff03152b7', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Matt Connor', 'Scott is an exceptional person and real estate professional. My wife and I had the pleasure to work with Scott in purchasing a home earlier this year. I highly recommend Scott for purchasing or selling your home or any other properties.', '2026-08-14T04:25:09.661678+00:00'),
  ('a3758aa9-7634-49d8-a7cf-5e720949d291', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Roy Morris', 'I recently had the pleasure of working with Scott Bird and I can''t recommend him enough! From start to finish, he was incredibly knowledgeable, responsive, and genuinely dedicated to helping me find my perfect home. His expertise in the market and attention to detail made the entire process seamless. Scott Bird was always available to answer my questions and provided valuable insights that made a big difference. If you''re looking for a realtor who truly cares and goes above and beyond, look no further!', '2026-08-14T04:25:09.661678+00:00'),
  ('5742fbaa-6f2c-429f-8afa-f883e244e758', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Roberta Counts', 'We hired Scott Bird for the sale of our vacation property in Cedar City Utah. We could not have chosen a better Realtor for our needs. He went above and beyond taking care of our house and assisted us in organizing contractors and inspectors. Scott is very conscientious and takes pride in his work. He is very proactive and patient. We were always happy to talk with Scott and never felt pressured or rushed. He gave us great advice on matters that we were not familiar with. We would highly recommend Scott Bird to anyone ready to buy or sell in Utah.', '2026-08-14T04:25:09.661678+00:00'),
  ('0e5c7d81-d367-4cfe-a843-1a7d48906b73', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Timoteo Scot', 'Scott was referred to us from a friend who used Scott''s services. Scott was always available to show us properties he thought we would like. He wasn''t pushy and was able to narrow down our search. We were able to find a home and Scott helped us throughout the entire process. We highly recommend Scott and his staff.', '2026-08-14T04:25:09.661678+00:00'),
  ('e0e6d10a-2820-4ab1-929f-2719454514f4', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Joe Baker', 'Scott Bird is the best! I highly recommend him for any real estate transaction. Scott saved me $1000s.', '2026-08-14T04:25:09.661678+00:00'),
  ('faafc797-8905-42a0-afa3-f6b47c9bffc1', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Susan Kaitukoff', 'We have known Scott Bird now for at least a decade...we love to come to Cedar City to stay for our annual ski trips and Scott has been our go-to guy for locations, and finding housing for us. He''s managed to guide us to both a house and condos at various times, and our experiences have always been excellent. He is quickly responsive to our requests, and any needs we may have while we''re there, and manages to get us the perfect place to stay every time. We like nice neighborhoods that are quiet and close enough to local amenities. Very, very happy with his services.', '2026-08-14T04:25:09.661678+00:00'),
  ('533959dd-f08c-4195-b813-c39fa0a78ee8', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Dallin Bird', 'Scott Bird was amazing throughout our entire home purchasing process. Moving into our first home we had lots of questions and concerns about what needs to be done, but Scott coached us through each step to becoming homeowners. Would highly recommend.', '2026-08-14T04:25:09.661678+00:00'),
  ('c2e59ca1-ad12-4bd1-974b-32be5ea0137d', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Marie Thurston', 'Scott is the best realtor that we have worked with. He went above and beyond what was required of him. Of course we would use him again in the future.', '2026-08-14T04:25:09.661678+00:00'),
  ('f36ea155-5889-44ca-be98-7ca1aed5f24e', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Katie Sparks', 'I''ve known Scott Bird for many years, and I can confidently say he''s one of the best in the business. Not only is Scott an incredibly knowledgeable Realtor with deep expertise in the Cedar City market, but he''s also a genuinely great guy who cares about his clients and community. Scott has built a reputation as someone you can trust—whether you''re buying, selling, or investing, you know you''re in good hands with him. He''s well-respected locally, always going the extra mile to make sure his clients get the best deal possible. If you''re looking for a realtor who knows his stuff and treats you like family, Scott is your guy!', '2026-08-14T04:25:09.661678+00:00'),
  ('4ee9e981-356d-40d1-b84c-6ee32123c56c', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Danielle Frey', 'Scott was amazing to work with. He was super patient even as we changed directions many times. He maintained his professionalism throughout our many visits! Being from out of town he provided information and details on neighborhoods and schools.', '2026-08-14T04:25:09.661678+00:00'),
  ('0935f51a-ae81-45cc-acb5-4f0a19290c98', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Amanda Wilcock', 'Scott helped us find our home 4 years ago and was an amazing agent to work with. He took all the aspects of our family needs, price range, and preferences into account and was candid with his thoughts about each home he showed us. As first time home buyers, he helped us understand the process and helped everything go so smoothly. The other Stratum people we worked with were great too, and Scott also gave us great references for other parts of the home-buying process. In the years since, Scott has continued to provide amazing service when we need information or help with anything home related. It''s so nice to know there''s someone we can call that is willing to give us an honest opinion and point us in the right direction. That integrity and service is priceless to us.', '2026-08-14T04:25:09.661678+00:00'),
  ('c9c3b643-3411-4a8c-ade9-9ed412ae4460', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Stacie Frehner', 'Best Realtor by far. Was always on top of everything and letting us know with every step. We greatly appreciated his help in selling my home in Cedar City Utah. I''m going to continue to refer friends and family to him. Scott Bird, thanks again for everything.', '2026-08-14T04:25:09.661678+00:00'),
  ('3067b41d-d893-4547-84fa-8d1df53b2d49', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Abimael Garcia', 'Scott did a wonderful job for us multiple times. We drove all over the place looking for property to buy and just about got stuck in the middle of a field. He spent a lot of time with us looking and consulting about opportunities. We found the perfect lot and we were able to navigate the transaction letting the seller lease back some of it. He then helped us get more money for our lot than another agent was offering. Without his help we wouldn''t have gotten market price. Thank you so much for all you did for us Scott!', '2026-08-14T04:25:09.661678+00:00'),
  ('e0ce75d6-ff3b-4cc3-bb31-bd7850cb0e99', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Alex Stout', 'Great to work with.', '2026-08-14T04:25:09.661678+00:00'),
  ('418a8d3e-f40f-437c-b57b-73e2983f6c78', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Dallen Jacoby', 'Scott was great to work with. He went out of his way to make sure every member of our family felt comfortable at every house he showed us. The home buying process could have been very stressful, but with Scott in our corner it went very smooth. Through Scott''s experience and advice, he helped us secure our first home at an amazing deal. I would recommend Scott to anyone. He is genuinely a great person. Our family will always be grateful to him for helping us realize our dream.', '2026-08-14T04:25:09.661678+00:00'),
  ('e6d8bd83-b2e4-419d-aaea-b78e0f757781', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Mitch Zundel', 'Scott is amazing! Highly recommend working with him and his team! Contact him for any of your real estate needs in and around Cedar City, Utah!', '2026-08-14T04:25:09.661678+00:00'),
  ('2a2fe97c-1b4c-465b-a0c9-53191a99adef', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Luke Stevens', 'Scott was extremely helpful in purchasing our new home. There was so much to juggle and for it being our first time buying a house, we had a lot we didn''t know. Scott was super responsive to questions and handled the majority of the legwork for helping us close on time. I would highly recommend Scott to any of my friends in the area looking to buy or sell.', '2026-08-14T04:25:09.661678+00:00'),
  ('e0c98c2d-9c93-4147-bb97-5085f188e600', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Marilla Jolley', 'It has been a great experience. I am so glad Scott is our realtor. He is the best. It has been, over all, a better experience than I could ever have thought it would be. Thank you.', '2026-08-14T04:25:09.661678+00:00'),
  ('ee67f30d-95db-4bae-a537-d8b88b70964c', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Tj Porter', 'Scott helped us find a home that fit just right. I am a first time buyer and he made the process easy and I learned a lot in the process. I would recommend Scott to help find the perfect place.', '2026-08-14T04:25:09.661678+00:00'),
  ('dc3f05ac-40e4-4227-a881-a40eb0013eed', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Makayla Adams', 'Scott was extremely helpful with trying to find a new home for our growing family. He was patient and kind as we were particular about what we wanted in our new place. He answered all the questions we had and was willing to work with our busy schedule. I will definitely recommend him to anyone that is buying a house!', '2026-08-14T04:25:09.661678+00:00'),
  ('c28b10a3-75f0-4629-97e5-7a528e1ce883', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Zach Adams', 'Scott is an asset you want on your team. He is patient, knowledgeable and will work through any situation to make sure your needs are met. I would recommend Scott to anyone looking for help while they navigate the real estate world.', '2026-08-14T04:25:09.661678+00:00'),
  ('111127d5-6039-4217-a07b-387b1f2359ca', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Jessie Jackson', 'My husband and I started our search for a home JUST before the crazy market explosion of 2021. When that started, we were still looking for our home. It was ROUGH. We put in bid after bid after bid, and kept getting outbid, sometimes with cash. Scott stuck with us through the entire, over-a-year-long, search. He went to so many houses with us! He was always on-time and always had a good attitude. He also got us some great concessions when we finally did close on our home.', '2026-08-14T04:25:09.661678+00:00'),
  ('d4be621c-31be-4bcd-88d7-a5d694a5a110', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Carolyn Myers', 'Scott is super awesome! Glad we had him help us. We''ve worked with him as a buyer and a seller. He''s super knowledgeable of the area and market. Our high end property needed a little extra attention. He went the extra mile to meet and made sure we were happy with the listing. Closing was super easy. Thanks Scott!', '2026-08-14T04:25:09.661678+00:00'),
  ('358e7576-a427-43a9-835d-9f82751a2b9e', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Darlene Hunter', 'Scott Bird was the realtor who helped me with the sale of my home. I had lived in my house, which had been my grandfather''s home before me, for more than fifty years. Words do not come easy if I try to explain how difficult the decision to sell was for me. Because of health reasons I had to move to a lower altitude. Scott just seemed to understand so well the emotions I was experiencing. He went out of his way many times to make it easier for me and to make everything go smoothly. He was especially kind and it made everything so much easier. Scott was professional, efficient and everything I would think one would want in a realtor. I''m very thankful that he was the one who sold my home for me. I would highly recommend him to anyone selling or buying a home.', '2026-08-14T04:25:09.661678+00:00'),
  ('96788cb7-7576-49e5-acb5-df839ad08f2b', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Kay Andersen', 'I highly recommend Scott Bird as you look to sell or buy real estate. He is a professional, personable, knows the business, will keep you informed, and work to get the best deal possible for you. It was a stress free experience for me having worked with him.', '2026-08-14T04:25:09.661678+00:00'),
  ('342c14a3-1459-444d-9fc4-4b03da26c0d8', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Elise Swenson', 'Scott is amazing to work with! He''s kind, knowledgeable, and sincere. He prioritizes his clients'' home buying & selling experience to ensure it''s as stress-free as possible. The Stratum Team is the best in Southern Utah!', '2026-08-14T04:25:09.661678+00:00'),
  ('5dea3db4-8f48-4f8e-a1bd-186c64bc6be1', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Rusty G.', 'I have only met and talked to Scott but he seems a very nice guy. Very interested in how things are going for those that he deals with, takes the interest of his clients seriously. I would certainly recommend him and his company to anyone. I''m sure that they would be well served.', '2026-08-14T04:35:25.3512+00:00'),
  ('0fdf9f2f-17ef-4c30-a457-fddfa1f0544f', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Beck Locey', 'Scott and his team were very helpful throughout the entire process of buying a property in southern Utah. They knew the area very well and knew of an inspector we could hire to inspect the property. They followed through on all the details of the transaction including tracking down a preliminary title report and zoning details of the property. Excellent service!', '2026-08-14T04:35:25.3512+00:00'),
  ('9bfca858-8fec-406d-878c-683c544fb1f7', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Sarah Barney', 'Scott was amazing to work with! We called him late one weekend and was the only agent out of 4 to respond. It was important to us that we keep our monthly payment under a certain amount, and Scott respected our decision and wouldn''t show us homes that were above that. He listened to our wants and needs and the first home we looked at...was it! Even though the home was a short sale, the process went very quickly. If we ever move again, we will be calling Scott...Thank you!!!', '2026-08-14T04:35:25.3512+00:00'),
  ('a1e93605-8ad2-4346-a53e-900f57e881ba', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Tamra Cooper', 'I would highly recommend working with Scott Bird to buy a home. He was so knowledgeable about all of our available options, options we didn''t even know we had. We were originally looking for a single-family home, but because of his good advice bought a duplex so we could rent out the other side and now our mortgage is basically paid for. He kept an eye out for properties for us and let us know immediately any that he thought would fit our needs. Scott did a fantastic job and is a fantastic agent. We would definitely work with him again and have referred him to numerous people.', '2026-08-14T04:35:25.3512+00:00'),
  ('17545ab0-1f08-48c2-8b6a-8139639c0d37', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Candace Robinson', 'I had contacted Scott when I found a condo in Parowan that he had listed. He was very helpful in helping get the condo under contract and through the rest of the process as well. He was very straight forward and easy to work with.', '2026-08-14T04:35:25.3512+00:00'),
  ('7a21583c-114c-4a69-8a00-40ef261eb159', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Dave Myers', 'We needed to see a home on a certain day in south central Utah. Scott worked for a few hours, made a bunch of phone calls and jumped through some hoops to make all the arrangements and we were able to see it THAT afternoon! We ended up buying the home, and perhaps it might not have been so had he not gone the extra mile to accommodate us and show us the home.', '2026-08-14T04:35:25.3512+00:00'),
  ('a2cef0db-9c68-4a7c-b319-56743615329f', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Although We Didn''t Buy', 'Although we did not buy a home in Cedar City, we really liked Scott and would recommend him. He constantly provided new listings and I really liked his portal. Very nice, competent agent.', '2026-08-14T04:35:25.3512+00:00'),
  ('13970869-c986-4c49-8641-1b7f696e13bc', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Peter B.', 'Working with Scott was a great experience. He was able to listen to our situation and help us sell our house. Our move was seamless. His effectiveness as a Realtor was exceptional so we strongly recommend working with Scott.', '2026-08-14T04:35:25.3512+00:00'),
  ('3115ab11-9e6d-4c90-a5b4-ff22993885cc', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Martinez & Wilnor', 'Scott helped us find our home in Cedar City. He came to us highly recommended, and after working with him, we can vouch that his reputation is absolutely well-deserved. He is a competent professional and a great pleasure to work with. The entire home-buying process went smoothly because of Scott''s masterful handling. We highly recommend him as a real estate agent if you are looking to buy your new home in Utah.', '2026-08-14T04:35:25.3512+00:00'),
  ('310aa22d-3da8-470f-8a48-ee81577479aa', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'L. Shasky', 'Scott Bird can do the impossible....find a willing buyer in a flat market. Although the bank ultimately refused to do a short sale, so we were unable to sell the house, Scott was able to stir up a lot of interest in our remote cabin in the wilderness. Thanks, Scott!', '2026-08-14T04:35:25.3512+00:00'),
  ('2f16c565-7184-495c-aedf-41d4fcb56da9', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Shayne Crapo', 'I highly encourage anyone looking for a realtor to use Scott Bird. He is knowledgeable, has integrity, and is able to find solutions to problems. For buying or selling, Scott will always do a great job in helping you with your Real Estate needs.', '2026-08-14T04:35:25.3512+00:00'),
  ('f91d6e25-cc3b-4900-a8ae-55313df9659a', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Wayne', 'I worked with Scott in 2010, he helped sell our Townhouse in Brian Head and we live in Las Vegas. Scott took care of everything and kept us updated at all times. Scott is very proactive and listens well. I would recommend Scott to anyone for their real estate needs.', '2026-08-14T04:35:25.3512+00:00'),
  ('8e5ed74d-847b-46c1-8367-eff95c3ae5ef', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'What a pleasure to work with Scott and his team! I would give higher marks if I could. Being miles away in CA, Scott was always in communication with me and was never in a rush which I appreciated. I was always kept in the loop on everything. During the closing of the sale things went quickly and without a hitch. Excellent team to work with. You are in very good hands with him.', '2026-08-14T04:35:25.3512+00:00'),
  ('2c68c65f-6f68-4731-836b-041fdc0b67da', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott was amazing in every aspect of the sale of our farm! He was available for phone calls, questions, etc., ALL the time. We live in CA, but he walked us through every step and got a price for us that was over and above what we anticipated. We will recommend Scott to others, and if the opportunity arises for us to relocate, he will be the first call we make!', '2026-08-14T04:35:25.3512+00:00'),
  ('363054a3-2fc4-4dc4-a896-573390167ac8', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Home Buyer', 'Scott and his team were great to work with; they labored for months to get me the perfect home. I was not the easiest person to satisfy, but they came to me with several options until they found the home that was just right. Scott is the quickest to reply and he and his crew are always willing to answer questions or find a solution. I''m now a happy home owner loving everything there is to love about my home.', '2026-08-14T04:35:25.3512+00:00'),
  ('52ce6f9f-ea2b-4310-b584-cb8336932783', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Vacation Home Buyer', 'On a whim and for fun we started to look at vacation property in Brian Head. Luckily we called Scott from one of his listings. Scott was patient, attentive, and knowledgeable. He took us through the steps and many options as we debated what we wanted in a vacation property. We love our cabin and I recommend Scott to anyone needing a realtor!', '2026-08-14T04:35:25.3512+00:00'),
  ('ae9935c6-a0c4-4bb2-9355-0bef7337a817', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Foreclosure Client', 'It was nice to have a kind and compassionate person knock on my door as we were going through this difficult time of foreclosure. The bank made no effort to help us or offer information. Scott was very helpful and always quick to respond to our inquiries. He was able to negotiate with the bank and get us cash for keys. I would highly recommend his services.', '2026-08-14T04:35:25.3512+00:00'),
  ('f7e4a79e-db63-4431-b9da-5e0618901bd6', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Brian Head Buyer', 'Scott helped us find the perfect home away from home in Brian Head! He was so patient with us as we looked at property after property. He dedicated his time and extensive resources, including his knowledge of the market in Brian Head, to help us find the perfect place during our 8 month search.', '2026-08-14T04:35:25.3512+00:00'),
  ('77e138f2-65d9-49e1-8be4-a5b1862462d7', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Riverton Buyer', 'Scott helped us buy our first house and has now been helping us with our second. He is very knowledgeable and great to work with. He''s a very positive person and easy to get along with. We really enjoy working with him.', '2026-08-14T04:35:25.3512+00:00'),
  ('713baa36-9695-4ebf-b3d1-e1924ab5dbec', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Relocating Buyer', 'I first spoke with Scott when my husband and I found out about a job transfer to Utah. He is very knowledgeable about his line of work and the area. Even through changing our minds many times on properties, Scott has stuck with us and has been patient. He was always on top of things. We really appreciate the no-nonsense approach that Scott has. He always says it like it is.', '2026-08-14T04:35:25.3512+00:00'),
  ('a7748e3c-2818-4e09-a00a-6266d2865c9b', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Foreclosure Buyer', 'Scott was incredible. I''m amazed at how well he understands and knows the foreclosure industry and process. We were able to have a smooth transaction when purchasing our newly owned foreclosed home. Scott told us from start to finish what and when to expect responses, inspections, closings, etc.', '2026-08-14T04:35:25.3512+00:00'),
  ('49ca7a14-a6bf-4554-96c3-fe7f26762cf4', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Cabin Buyer', 'I would recommend Scott to anyone trying to purchase property. He took me to the cabin that I ended up buying in January on a snowmobile! He pointed out things that I should be aware of, and gave me ideas of what and how to improve things that were not quite right.', '2026-08-14T04:35:25.3512+00:00'),
  ('3e4edae7-7a2b-46f8-ab6a-9c322bb0cb20', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Tammy Saly', 'We loved working with Scott. He was always available whenever we needed to ask a question or see a property. He''s very knowledgeable, honest and patient. It took us a while to figure out what we wanted, he was always so nice about it! Thanks so much Scott! We definitely will work with you again! And of course we tell everyone about you and the awesome job you did for us!', '2026-08-14T04:35:25.3512+00:00'),
  ('c07c721e-54c2-4b38-8c66-a4be7b5532a1', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Condo Buyer', 'Scott helped me get into my Condo at Brian Head. It was a short sale that could have been a really long, drawn out process, but he helped make it run quickly and smoothly. After purchase, there was a lock problem, but Scott found a locksmith for me and had everything taken care of even though his part was already done. I would recommend Scott to my family and friends.', '2026-08-14T04:35:25.3512+00:00'),
  ('173de4ed-a659-4971-b76f-3552dfd5e9dc', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'We would recommend Scott and his team at Stratum Real Estate Group when buying a home in the Cedar City area. Finding a suitable home was easy because they made a strong and very effective effort to match our needs and requests, saving us a lot of time. Buying a foreclosed home is a lengthy process, but Scott and his team made every effort to make the purchase run as smoothly as possible. Thanks!', '2026-08-14T04:35:25.3512+00:00'),
  ('787f80d9-d399-4908-b167-de0612ebab5e', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Buyer', 'It was a delight to work with Scott. He was always quick to respond and very flexible to work around my busy schedule. It was also nice to have someone so personable and knowledgeable about the market. I would recommend working with Scott to anyone. Thanks again Scott for the great service!', '2026-08-14T04:35:25.3512+00:00'),
  ('6082fb34-4015-479b-9881-fbcdc2c80b7d', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Cedar City Business Owner', 'Scott and his team have been a valuable resource to me in many different ways. They helped negotiate a great lease agreement as we moved our office for the first time in 14 years. We are very happy in our new space and have a lease that works well for our company. Scott is easy to get a hold of, has an exhaustive knowledge of the local market, an excellent negotiator and a great person.', '2026-08-14T04:35:25.3512+00:00'),
  ('80dffe83-5f35-4498-86e8-cde3a75c111f', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Rich Lisa', 'Scott was great. He found us the property we were looking for, and a great deal. And was patient working with the banks, since we had a short sale. I would definitely use him again. He understood the contract and all the things that had to go on to purchase a home.', '2026-08-14T04:35:25.3512+00:00'),
  ('a458dcc7-69c1-46a6-abea-900687ddeea3', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Betty Ann Thomas', 'Scott and his team did a fantastic job selling my Brian Head cabin lot. They stayed on top of things and had very good advice about pricing. I very much appreciate all they did to help me and would definitely recommend them to anyone!', '2026-08-14T04:35:25.3512+00:00'),
  ('15003f9b-2882-4bcf-95ba-5fc7be4350c1', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Angelica Judd', 'Scott and his team are an exceptional team to work with! Scott was quick to send paperwork and get photos online of my home. They were available to answer my calls or texts and answer my 100 questions about the selling process.', '2026-08-14T04:35:25.3512+00:00'),
  ('cc294c2d-4dc1-4f66-b62d-5eb11dc623d3', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Bradford McColl', 'I worked with this team as an out of state buyer on a small dollar amount condo purchase and they treated my transaction like it was a multi million dollar deal. This team personifies customer excellence. They are personally responsive at all hours of the day and worked their tails off to help in any way they could, often above and beyond expectations. Highly recommend this team of professionals, they are the best!', '2026-08-14T04:35:25.3512+00:00'),
  ('3b37bc7b-a104-4d93-8d3d-242937d9e238', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Joey Garrett', 'Scott is a great guy and a great realtor. He is upfront and honest with you. When we were getting ready to list our home, he brought us into his office and we started looking at comparable sales. This helped us come up with a competitive listing price for our home. He then came out and looked at the home and gave us suggestions that we could do to the house, to make it more marketable. I have recommended people to Scott and will continue to do so.', '2026-08-14T04:35:25.3512+00:00'),
  ('086af0a4-414c-41f4-9414-82191d3c9f6e', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'David Louthan', 'The "Bird Team" was very responsive and I could trust them to make things happen when they were time sensitive. I highly recommend them to anyone buying or selling. I plan to use them again in the future.', '2026-08-14T04:35:25.3512+00:00'),
  ('f8777a18-0a7b-4fc7-a54a-ab2f7f08b4c6', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Peter Clark', 'I''ve known Scott for years, but only recently had the opportunity to use him professionally to help us sell our home. The process was quick and seamless. Scott was able to alert us to the few issues that crept up along the way, and we did all of this while from out of state. I would definitely recommend him to others. While not a word to be overused, I think to say that Scott has integrity is a very accurate descriptor. I have no issue trusting him and his advice.', '2026-08-14T04:35:25.3512+00:00'),
  ('4700ba1a-c539-4dfd-b9d7-f882b22aaaba', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Cedar City Homebuyer', 'My husband and I lived in Salt Lake City and we decided to take a little drive one summer day and we ended up in Cedar City. We contacted Scott about a house but missed it by a day, so Scott helped us out on a few houses, and then his team helped us out too. We were not sure about living in Cedar City, but once we''d been shown a lot of houses we knew we were meant to live here. Scott and his team labored for a few months helping us get into our perfect house. Every time we went into the Stratum office we always felt welcomed, and they always took time out to help us, even late at night. I would highly encourage anyone looking for a realtor to use Scott and his team. We love our home!', '2026-08-14T04:45:47.702938+00:00'),
  ('96239652-5767-430b-b737-cff20c42eec8', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'I must say very professional and attentive in all details of the transaction. We definitely would recommend Scott and his team for any real estate needs. From the very beginning of the listing up until the closing of escrow, the updates were very timely and accurate. They were always there if anything extra was needed.', '2026-08-14T04:48:28.944919+00:00'),
  ('7e31989f-b20c-4f34-9e55-b0c9b4154540', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'They really listened to what I wanted in a home. They spent a lot of time reviewing the documents I was signing. They worked around the clock showing me home after home, until I found the home just for me!', '2026-08-14T04:48:28.944919+00:00'),
  ('bd848954-6c12-4072-b6cb-eec20e08a14e', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'We have worked with Scott and his team before. They were very quick to respond and do all they can for us. We are very confident in working with them!', '2026-08-14T04:48:28.944919+00:00'),
  ('802b1063-c5e8-40e0-a505-ed047468414e', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott helped us sell our investment property in Cedar City. He was very knowledgeable about market conditions, did excellent research on pricing for comparable homes, and helped us set an appropriate price that allowed us to achieve our goals and sell the property quickly. Scott did a great job helping us negotiate offers and counter-offers. Highly recommend him for a good selling experience.', '2026-08-14T04:48:28.944919+00:00'),
  ('c92dda0f-979b-42af-97dd-8a068fa4c989', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Excellent results from Scott and his team. They always got back to us quickly and with answers! Got all the paperwork together and handled this very unique sale. We highly recommend them.', '2026-08-14T04:48:28.944919+00:00'),
  ('0743964c-84d1-46e1-97a5-686de2e1aaa7', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'My wife and I have been looking for a home in the Cedar area for almost three years. We have been working with Scott''s team that long to find a home that will meet our needs. Every time I would ask for help or a last minute showing they were happy to show us homes. We finally found the home for us and Scott''s team moved quickly to ensure we secured it. Thanks again for excellent service and a job well done.', '2026-08-14T04:48:28.944919+00:00'),
  ('9817cd7e-899b-447e-85b1-b8df553da73d', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'For several months, my husband and I were struggling to find a home that would fit our needs — we have animals and wanted acreage. We went through a lot of bidding battles and nothing ever panned out. We started working with Scott''s team and within 1 week they found us the perfect home. They were very knowledgeable, always available, and kept us up to date throughout the buying process. We were so impressed that we recommended them to my parents, who were also looking for a second home in Cedar.', '2026-08-14T04:48:28.944919+00:00'),
  ('ca8df79e-5554-4ee1-a637-2bcc42fa266e', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott is very knowledgeable and did a great job for me. We had a challenging deal and he was detail oriented and extremely persistent. Every obstacle we met he had a solution for and made things happen in a timely and professional manner. I would highly recommend Scott and his team for any type of real estate transaction. I would not go to another agent in Southern Utah.', '2026-08-14T04:48:28.944919+00:00'),
  ('c4e7a429-2746-456d-ab39-4fd9c6cf0e92', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'My experience with Scott''s team has been great. I wanted an agent who was honest and knowledgeable and found that in them. I have found that working with younger people than myself, they bring a different perspective to things that is very refreshing.', '2026-08-14T04:48:28.944919+00:00'),
  ('da76b5f3-5615-40cd-a7ad-bc9e9830ddd2', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'I was more than impressed with Scott''s team. They were very easy to work with, very knowledgeable, and gave great advice. I would recommend them to anyone. They made selling our old home and purchasing our new one a very easy transition. They were well organized and always kept us well informed.', '2026-08-14T04:48:28.944919+00:00'),
  ('e53a915f-dcd0-4b2a-9819-81062992b29a', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott bent over backwards to work with both the buyer and the seller. He sold our property and represented us well and is extremely honest and forthright in his dealings. I would recommend him to anyone.', '2026-08-14T04:48:28.944919+00:00'),
  ('173fd245-f9c3-4e95-8bdf-790a0c3b0d29', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott and his team were very helpful in my recent property purchase. They responded quickly to inquiries and were able to get the transaction processed very quickly. I would highly recommend them and would gladly use their services in the future.', '2026-08-14T04:48:28.944919+00:00'),
  ('a1712df3-3bb1-4bea-a149-cf8b6e27d5ea', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott Bird and his team helped us buy a property. Their local knowledge is incredible! They found this amazing property and helped us buy it, and are now selling another property for us. We highly recommend Scott Bird and his team for their exceptional knowledge of the market.', '2026-08-14T04:48:28.944919+00:00'),
  ('c8d22108-7f17-45fb-b98e-6ceff92289d0', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott was very helpful and responsive when my wife and I were looking for a place to rent in Cedar City. There was one time that water had flooded into the basement and damaged some furniture. Scott was right on top of it and had the carpet replaced immediately and the furniture fixed as well. We enjoyed working with Scott and highly recommend him.', '2026-08-14T04:48:28.944919+00:00'),
  ('f05c1f70-c009-4a57-8731-470c7a4f15ab', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'I only had a little interaction with Scott, but he was very helpful in connecting me with a local agent to assist in viewing and purchasing his listing. He was responsive and friendly.', '2026-08-14T04:48:28.944919+00:00'),
  ('5cac9d09-896b-4bf2-9c11-f5a29554356a', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott Bird is extremely knowledgeable about the local area. I especially liked how humble he was and how much he was focused on finding me a good property, not a good sale for him. I would recommend him to friends and family for sure!', '2026-08-14T04:48:28.944919+00:00'),
  ('c29838ea-8fa0-45b2-9b11-7245066f390d', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott and his team helped me with every step of the buying process, and even continued to lend me advice after the sale relating to the property. They always got back to me and made sure I knew what was going on.', '2026-08-14T04:48:28.944919+00:00'),
  ('6938583d-6df3-402f-a6d8-fd8cd2d7b577', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott is great. The deal took a while but he stayed on the bank for us. We highly recommend Scott for any real estate transactions you have. Couldn''t have asked for more. Thanks.', '2026-08-14T04:48:28.944919+00:00'),
  ('2542f089-8f07-43cb-99a7-576207bf0185', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott helped me sell my home quickly. He is professional and knows the market. He was able to let me know what buyers were looking for and got the most money for my home. He responded quickly to phone calls and questions. I highly recommend Scott.', '2026-08-14T04:48:28.944919+00:00'),
  ('c4b1aceb-8bd7-4989-a882-c15ac7cbfb38', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'This sale was unusual in some ways and Scott dealt with it in a professional manner, always doing what was best for me. He was quick to respond and answered questions with confidence and honesty. He did everything he could to get a great offer for my home. I highly recommend Scott.', '2026-08-14T04:48:28.944919+00:00'),
  ('6d531a5f-dbef-4089-84b8-bf26e5042220', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'I have used Scott and his team twice now and both times he has done a fabulous job for me. He does his research prior to listing the property so that you know what the comps are you will be competing against in the market.', '2026-08-14T04:48:28.944919+00:00'),
  ('fb620b02-847d-4a58-93c3-c32ae7977272', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott Bird and his team were very helpful and professional. Good communication. They worked with the Bank and Title company to iron out the details and expedited the transactions while I was out of town.', '2026-08-14T04:48:28.944919+00:00'),
  ('94cb61ea-ba62-4d00-8e0f-a457734c0513', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Scott Bird took the time to thoroughly explain the selling process, was always available to answer my questions and did his research toward a successful sale of my lot. I would highly recommend him to anyone interested in selling their house or property.', '2026-08-14T04:48:28.944919+00:00'),
  ('991b1a8b-655c-4270-ba4b-fd6823c11fb9', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'If you are looking for real estate in or around beautiful Cedar City, Utah, look no further than Scott Bird. He and his team are THE most genuinely personal and qualified real estate professionals that we have EVER encountered in our 40 years of real estate buying and investing. Because he is a qualified buyer, seller, and intermediary representative, you can trust that he goes the extra mile to accommodate all parties, always retaining a high degree of integrity in transactions. Our recent experience with Scott couldn''t have been more positive after driving 9 hours from Colorado to see property — his team will go not only the extra mile, but countless miles to patiently help you find what you are looking for.', '2026-08-14T04:48:28.944919+00:00'),
  ('b968ba2d-c5ee-41c7-bb28-849b5df1d2a8', '72158799-b0f4-47c9-ac2a-45ffe52db1df', 'Verified Zillow Review', 'Our experience with Scott and his team was EXCELLENT! Very professional and courteous. Returned calls immediately. They are very knowledgeable and pleasant to work with. In the past we had put our property up for sale and did not sell with a previous agent — with Scott, he right away had a buyer. We are glad we chose him to help us sell our property.', '2026-08-14T04:48:28.944919+00:00')
